package com.phoenix.business.domain;
import jakarta.persistence.*; import lombok.*; import java.time.Instant;
@Entity @Table(name="business_settings") @Getter @Setter @NoArgsConstructor
public class BusinessSettings { @Id private Long id=1L; @Column(name="gym_name",nullable=false) private String gymName; private String phone; private String email; private String address; @Column(nullable=false) private String currency="INR"; @Column(name="time_zone",nullable=false) private String timeZone="Asia/Kolkata"; @Column(name="logo_url") private String logoUrl; @Column(name="receipt_footer") private String receiptFooter; @Column(name="tax_identifier") private String taxIdentifier; @Column(name="reminder_days",nullable=false) private int reminderDays=7; @Column(name="allow_multiple_daily_checkins",nullable=false) private boolean allowMultipleDailyCheckins; @Column(name="created_at",insertable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",insertable=false,updatable=false) private Instant updatedAt; }
